-- Check all FK constraints on interactions referencing fans
SELECT conname, confdeltype FROM pg_constraint 
WHERE conrelid = 'interactions'::regclass AND confrelid = 'fans'::regclass;

-- Check all FK constraints on membershipandspending referencing fans
SELECT conname, confdeltype FROM pg_constraint 
WHERE conrelid = 'membershipandspending'::regclass AND confrelid = 'fans'::regclass;

WITH to_delete AS (
    SELECT notesreg FROM additionalnotes 
    WHERE notesretainpivot IN (SELECT retreg FROM retentionandinfluence WHERE churnflag IN ('High', 'Medium'))
)
DELETE FROM additionalnotes WHERE notesreg IN (SELECT notesreg FROM to_delete) RETURNING *;
